function searchRange(nums, target) {
  const lb = (t) => { let lo = 0, hi = nums.length; while (lo < hi) { const m = (lo + hi) >> 1; if (nums[m] < t) lo = m + 1; else hi = m; } return lo; };
  const a = lb(target);
  if (a === nums.length || nums[a] !== target) return [-1, -1];
  return [a, lb(target + 1) - 1];
}
